      "keystrokes": "cat > main.cpp <<'CPP'\n#include <bits/stdc++.h>\nusing namespace std;\n\nstruct Point { double x, y; };\nconst double EPS = 1e-9;\n\ndouble cross(const Point& a, const Point& b){ return a.x*b.y - a.y*b.x; }\ndouble dotp(const Point& a, const Point& b){ return a.x*b.x + a.y*b.y; }\nPoint operator+(const Point& a, const Point& b){ return {a.x+b.x, a.y+b.y}; }\nPoint operator-(const Point& a, const Point& b){ return {a.x-b.x, a.y-b.y}; }\nPoint operator*(const Point& a, double k){ return {a.x*k, a.y*k}; }\n\nbool point_on_segment(const Point& p, const Point& a, const Point& b){\n  if (fabs(cross(p - a, b - a)) > 1e-9) return false;\n  double dot = dotp(p - a, b - a);\n  if (dot < -1e-9) return false;\n  double len2 = dotp(b - a, b - a);\n  if (dot > len2 + 1e-9) return false;\n  return true;\n}\n\ntypedef struct { bool exists; double s; Point X; } InterInfo;\nInterInfo seg_intersect_params(const Point& p1, const Point& p2, const Point& q1, const Point& q2){\n  Point d1 = p2 - p1; Point d2 = q2 - q1;\n  double den = cross(d1, d2);\n  InterInfo out{false,0,{0,0}};\n  if (fabs(den) < 1e-12) return out;\n  Point w = q1 - p1;\n  double s = cross(w, d2) / den;\n  double t = cross(w, d1) / den;\n  if (s >= -1e-12 && s <= 1+1e-12 && t >= -1e-12 && t <= 1+1e-12){\n    out.exists = true; out.s = s; out.X = {p1.x + d1.x*s, p1.y + d1.y*s};\n  }\n  return out;\n}\n\nbool isDirectVisible(const Point& P, const Point& L, const vector<Point>& poly){\n  int n = poly.size();\n  for (int i=0;i<n;i++){\n    Point A = poly[i], B = poly[(i+1)%n];\n    InterInfo II = seg_intersect_params(L, P, A, B);\n    if (!II.exists) continue;\n    if (fabs(II.s - 1.0) < 1e-9){\n      if (point_on_segment(P, A, B)){\n        continue;\n      } else {\n        return false;\n      }\n    }\n    if (II.s > 1e-9 && II.s < 1 - 1e-9){\n      return false;\n    }\n  }\n  return true;\n}\n\nbool point_in_polygon(const Point& p, const vector<Point>& poly){\n  int n = poly.size();\n  for (int i=0;i<n;i++){\n    if (point_on_segment(p, poly[i], poly[(i+1)%n])) return true;\n  }\n  bool inside = false;\n  for (int i=0, j=n-1; i<n; j=i++){\n    Point a = poly[i], b = poly[j];\n    bool intersect = ((a.y > p.y) != (b.y > p.y)) &&\n      (p.x < (b.x - a.x) * (p.y - a.y) / (b.y - a.y) + a.x);\n    if (intersect) inside = !inside;\n  }\n  return inside;\n}\n\nbool segment_inside_polygon(const Point& A, const Point& B, const vector<Point>& poly){\n  int samples = 12;\n  for (int k=1; k<samples; k++){\n    double t = double(k)/samples;\n    Point X{A.x*(1-t) + B.x*t, A.y*(1-t) + B.y*t};\n    if (!point_in_polygon(X, poly)) return false;\n  }\n  return true;\n}\n\nPoint reflect_point_across_line(const Point& P, const Point& A, const Point& B){\n  Point AB = B - A;\n  double t = dotp(P - A, AB) / dotp(AB, AB);\n  Point proj = A + AB * t;\n  return {2*proj.x - P.x, 2*proj.y - P.y};\n}\n\ntypedef struct { Point p; double s; bool lit; int edge; } Sample;\n\nint main(){\n  ios::sync_with_stdio(false);\n  cin.tie(nullptr);\n  int N;\n  cout.setf(std::ios::fixed); cout<<setprecision(3);\n  while ( (cin>>N) ){\n    if (N==0) break;\n    vector<Point> poly(N);\n    for (int i=0;i<N;i++) cin>>poly[i].x>>poly[i].y;\n    Point L; cin>>L.x>>L.y;\n\n    const int K = 60; // samples per edge\n    vector<double> edgeLen(N); double perimeter = 0.0;\n    for (int i=0;i<N;i++){\n      Point A = poly[i], B = poly[(i+1)%N];\n      double len = hypot(B.x - A.x, B.y - A.y);\n      edgeLen[i] = len; perimeter += len;\n    }\n\n    vector<Sample> samples; samples.reserve(N*(K+1));\n    double cum = 0.0;\n    for (int i=0;i<N;i++){\n      Point A = poly[i], B = poly[(i+1)%N]; double len = edgeLen[i];\n      for (int j=0;j<=K;j++){\n        double t = double(j)/K;\n        Point P{A.x + t*(B.x - A.x), A.y + t*(B.y - A.y)};\n        double s = cum + t*len;\n        samples.push_back({P, s, false, i});\n      }\n      cum += len;\n    }\n\n    // Deduplicate consecutive identical points (at vertices)\n    vector<Sample> uniq; uniq.reserve(samples.size());\n    for (size_t i=0;i<samples.size();i++){\n      if (uniq.empty()) uniq.push_back(samples[i]);\n      else {\n        Point a = uniq.back().p, b = samples[i].p; double dx = a.x - b.x, dy = a.y - b.y;\n        if (dx*dx + dy*dy > 1e-60) uniq.push_back(samples[i]);\n      }\n    }\n    samples.swap(uniq);\n    int M = samples.size();\n\n    // Determine visibility for each sample (direct or one-reflection)\n    for (int i=0;i<M;i++){\n      Point P = samples[i].p;\n      bool lit = isDirectVisible(P, L, poly);\n      if (!lit){\n        for (int e=0;e<N && !lit;e++){\n          Point A = poly[e], B = poly[(e+1)%N];\n          Point Lp = reflect_point_across_line(L, A, B);\n          Point d1 = P - Lp; Point d2 = B - A; Point w = A - Lp;\n          double den = cross(d1, d2);\n          if (fabs(den) < 1e-12) continue;\n          double sparam = cross(w, d2) / den;\n          double tparam = cross(w, d1) / den;\n          if (sparam >= -1e-12 && sparam <= 1+1e-12 && tparam >= -1e-12 && tparam <= 1+1e-12){\n            Point Pint = {Lp.x + d1.x * sparam, Lp.y + d1.y * sparam};\n            if (point_on_segment(Pint, A, B)){\n              if (isDirectVisible(Pint, L, poly) && segment_inside_polygon(Pint, P, poly)){\n                lit = true; break;\n              }\n            }\n          }\n        }\n      }\n      samples[i].lit = lit;\n    }\n\n    // Sum lit length along boundary by aggregating per-sample intervals\n    double lit_len = 0.0;\n    for (int i=0;i<M;i++){\n      int j = (i+1)%M;\n      double ds = samples[j].s - samples[i].s; if (ds < 0) ds += perimeter;\n      if (samples[i].lit || samples[j].lit) lit_len += ds;\n    }\n\n    cout << lit_len << \"\\n\";\n  }\n  return 0;\n}\nCPP\n\ng++ -std=c++17 -O2 -pipe -static -s -o main main.cpp\n./main << EOF\n4\n0 0\n2 0\n2 2\n0 2\n1 1\n6\n2 2\n2 5\n0 5\n0 0\n5 0\n5 2\n1 4\n0\nEOF",
