cutive identical points (at vertices)\n    vector<Sample> uniq; uniq.reserve(samples.size());\n    for (size_t i=0;i<samples.size();i++){\n      if (uniq.empty()) uniq.push_back(samples[i]);\n      else {\n        Point a = uniq.back().p, b = samples[i].p; double dx = a.x - b.x, dy = a.y - b.y;\n        if (dx*dx + dy*dy > 1e-60) uniq.push_back(samples[i]);\n      }\n    }\n    samples.swap(uniq);\n    int M = samples.size();\n\n    // Determine visibility for each sample (direct or one-reflection)\n    for (int i=0;i<M;i++){\n      Point P = samples[i].p;\n      bool lit = isDirectVisible(P, L, poly);\n      if (!lit){\n        for (int e=0;e<N && !lit;e++){\n          Point A = poly[e], B = poly[(e+1)%N];\n          Point Lp = reflect_point_across_line(L, A, B);\n          Point d1 = P - Lp; Point d2 = B - A; Point w = A - Lp;\n          double den = cross(d1, d2);\n          if (fabs(den) < 1e-12) continue;\n          double sparam = cross(w, d2) / den;\n          double tparam = cross(w, d1) / den;\n          if (sparam >= -1e-12 && sparam <= 1+1e-12 && tparam >= -1e-12 && tparam <= 1+1e-12){\n            Point Pint = {Lp.x + d1.x * sparam, Lp.y + d1.y * sparam};\n            if (point_on_segment(Pint, A, B)){\n              if (isDirectVisible(Pint, L, poly) && segment_inside_polygon(Pint, P, poly)){\n                lit = true; break;\n              }\n            }\n          }\n        }\n      }\n      samples[i].lit = lit;\n    }\n\n    // Sum lit length along boundary by aggregating per-sample intervals\n    double lit_len = 0.0;\n    for (int i=0;i<M;i++){\n      int j = (i+1)%M;\n      double ds = samples[j].s - samples[i].s; if (ds < 0) ds += perimeter;\n      if (samples[i].lit || samples[j].lit) lit_len += ds;\n    }\n\n    cout << lit_len << \"\\n\";\n  }\n  return 0;\n}\nCPP\n\ng++ -std=c++17 -O2 -pipe -static -s -o main main.cpp\n",
