      "keystrokes": "cat > main.cpp << 'CPP'\n#include <bits/stdc++.h>\nusing namespace std;\n\n// Segment Tree with lazy range-assign and Misra-Gries style candidate merging\n\nstruct SegTree {\n    int n;          // size\n    int K;          // max number of candidates per node\n    vector<int> a;  // 1-based initial array\n    struct Node {\n        vector<pair<int,int>> cand; // (id, count)\n        int tag;                    // 0 means no tag; otherwise whole segment is assigned to tag id\n    };\n    vector<Node> st;\n\n    SegTree(int _n, const vector<int>& arr, int K_) {\n        n = _n;\n        a = arr;\n        K = max(1, K_);\n        st.resize(4*n + 4);\n        build(1, 1, n);\n    }\n\n    static vector<pair<int,int>> mergeCand(const vector<pair<int,int>>& A, const vector<pair<int,int>>& B, int K) {\n        if (A.empty()) return B;\n        if (B.empty()) return A;\n        vector<pair<int,int>> res = A;\n        auto add = [&](int id, int cnt){\n            int curId = id;\n            int curCnt = cnt;\n            while (curCnt > 0) {\n                bool found = false;\n                for (auto &pp : res) if (pp.first == curId) { pp.second += curCnt; found = true; break; }\n                if (found) { curCnt = 0; break; }\n                if ((int)res.size() < K) { res.push_back({curId, curCnt}); curCnt = 0; break; }\n                int minCnt = INT_MAX;\n                for (auto &pp : res) minCnt = min(minCnt, pp.second);\n                int dec = min(curCnt, minCnt);\n                for (auto &pp : res) pp.second -= dec;\n                vector<pair<int,int>> newRes; newRes.reserve(res.size());\n                for (auto &pp : res) if (pp.second > 0) newRes.push_back(pp);\n                res.swap(newRes);\n                curCnt -= dec;\n            }\n        };\n        for (const auto &p : B) add(p.first, p.second);\n        if ((int)res.size() > K) res.resize(K); // safeguard\n        return res;\n    }\n\n    void build(int p, in